parse_quantity(text) -> (value_in_SI, dimension_tuple)

Supported syntax:
    <number> [<unit-term> (('*' | '/') <unit-term>)*]
    <unit-term> := <unit-symbol> ['^' <integer>]

SI prefixes supported: k (1e3), M (1e6), m (1e-3), c (1e-2),
u (1e-6), n (1e-9), and h (1e2, hecto).

HECTO SPECIAL CASE (documented): the 'h' symbol is ambiguous -- it means
"hour" as a standalone unit, but acts as the hecto (1e2) prefix ONLY when
directly attached to 'Pa' or 'L' (pressure/volume cases, e.g. 'hPa', 'hL').
Everywhere else 'h' is 3600 seconds. This matches real-world usage
('hPa' is ubiquitous; 'hhour' is not a thing).

Base dimensions are ordered: (meter, kilogram, second, ampere,
kelvin, mole, candela).

Known ambiguity (documented): when a symbol admits several readings, the
LONGEST unit-name match wins, so 'ms' parses as millisecond, not
meter-second. Use explicit '*' to disambiguate ('m*s').
"""

import re

__all__ = ["ParseError", "parse_quantity", "format_quantity"]


class ParseError(ValueError):
    """Raised when a quantity string cannot be parsed."""


# ---------------------------------------------------------------------------
# Unit tables
# ---------------------------------------------------------------------------

# Base dimension order: m, kg, s, A, K, mol, cd
BASE_NAMES = ("m", "kg", "s", "A", "K", "mol", "cd")

# name -> (factor_to_SI, {base_name: exponent})
UNITS = {
    "m":  (1.0, {"m": 1}),                                   # meter
    "s":  (1.0, {"s": 1}),                                   # second
    "g":  (1e-3, {"kg": 1}),                                 # gram -> kg
    "N":  (1.0, {"kg": 1, "m": 1, "s": -2}),                 # newton
    "J":  (1.0, {"kg": 1, "m": 2, "s": -2}),                 # joule
    "W":  (1.0, {"kg": 1, "m": 2, "s": -3}),                 # watt
    "Pa": (1.0, {"kg": 1, "m": -1, "s": -2}),                # pascal (N/m^2)
    "L":  (1e-3, {"m": 3}),                                  # liter -> m^3
    "h":  (3600.0, {"s": 1}),                                # hour -> s
    "eV": (1.602176634e-19, {"kg": 1, "m": 2, "s": -2}),     # exact, SI 2019
}

PREFIXES = {
    "k": 1e3,
    "M": 1e6,
    "m": 1e-3,
    "c": 1e-2,
    "u": 1e-6,
    "n": 1e-9,
    "h": 1e2,  # hecto: only valid attached to Pa/L (see module docstring)
}

HECTO_ALLOWED = {"Pa", "L"}

_NUMBER_RE = re.compile(r"[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?")
_EXPONENT_RE = re.compile(r"[+-]?\d+")


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _dim_tuple(dim_dict):
    return tuple(dim_dict.get(base, 0) for base in BASE_NAMES)


def _resolve_symbol(name, pos):
    """Resolve an alphabetic run like 'km', 'hPa', 'ug', 'eV' to (factor, dims).

    Preference order: longest unit-name match first (shortest prefix).
    """
    for cut in range(len(name)):
        prefix, unit = name[:cut], name[cut:]
        if unit not in UNITS:
            continue
        factor, dims = UNITS[unit]
        if prefix == "":
            return factor, dict(dims)
        if prefix not in PREFIXES:
            continue
        if prefix == "h" and unit not in HECTO_ALLOWED:
            continue  # 'h' is 'hour' here, not hecto
        return factor * PREFIXES[prefix], dict(dims)
    hint = ""
    if name.startswith("h") and name[1:] not in HECTO_ALLOWED and name != "h":
        hint = " (note: 'h' is hour, or hecto only when attached to Pa/L)"
    raise ParseError(
        f"unknown unit {name!r} at position {pos}{hint}"
    )


def _parse_unit_expression(expr):
    """Parse a unit expression like 'kg*m^2/s^2'. Returns (factor, dim_tuple)."""
    factor = 1.0
    dims = {}
    i = 0
    first = True

    while True:
        # Operator (implicit multiplication is NOT allowed; first term needs none)
        if not first:
            if i >= len(expr):
                raise ParseError(
                    f"dangling operator at end of unit expression {expr!r}: "
                    f"expected a unit symbol after {expr.rsplit('/', 1)[-1] and expr[-1]!r}"
                )
            op = expr[i]
            if op not in "*/":
                raise ParseError(
                    f"expected '*' or '/' at position {i} in unit expression "
                    f"{expr!r}, got {op!r}"
                )
            sign = 1 if op == "*" else -1
            i += 1
        else:
            sign = 1

        # Symbol: maximal alphabetic run
        j = i
        while j < len(expr) and expr[j].isalpha():
            j += 1
        name = expr[i:j]
        if not name:
            if i >= len(expr):
                raise ParseError(
                    f"dangling {expr[i - 1]!r} at end of unit expression "
                    f"{expr!r}: expected a unit symbol after the operator"
                )
            raise ParseError(
                f"expected a unit symbol at position {i} in {expr!r}, "
                f"got {expr[i]!r}"
            )

        sym_factor, sym_dims = _resolve_symbol(name, i)

        # Optional integer power: ^2, ^-3, ^+2
        exponent = 1
        if j < len(expr) and expr[j] == "^":
            k = j + 1
            m = _EXPONENT_RE.match(expr, k)
            if not m:
                raise ParseError(
                    f"expected an integer exponent after '^' at position {j} "
                    f"in {expr!r}"
                )
            exponent = int(m.group())
            j = m.end()

        factor *= sym_factor ** exponent if False else sym_factor  # placeholder
        factor = factor  # noqa
        # (apply properly below)

        # Apply symbol factor once per exponent via multiplication
        # (sym_factor ** exponent is equivalent for positive factors)
        factor = factor / sym_factor  # undo placeholder line
        factor = factor * (sym_factor ** exponent)
        if sign < 0:
            factor = factor / (sym_factor ** (2 * exponent))

        for base, exp in sym_dims.items():
            dims[base] = dims.get(base, 0) + sign * exponent * exp

        i = j
        first = False

        if i == len(expr):
            break
        if expr[i] not in "*/":
            raise ParseError(
                f"unexpected character {expr[i]!r} at position {i} in unit "
                f"expression {expr!r} (use '*' or '/' between units)"
            )

    return factor, _dim_tuple(dims)


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def parse_quantity(text):
    """Parse a quantity string into (value_in_SI, dimension_tuple).

    Examples:
        >>> parse_quantity("120 km/h")
        (33.333333333333336, (1, 0, -1, 0, 0, 0, 0))
        >>> parse_quantity("1013.25 hPa")
        (101325.0, (-1, 1, -2, 0, 0, 0, 0))
    """
    if not isinstance(text, str):
        raise ParseError(
            f"expected a string, got {type(text).__name__}: {text!r}"
        )
    s = text.strip()
    if not s:
        raise ParseError("empty input: expected '<number> [<units>]'")

    m = _NUMBER_RE.match(s)
    if not m or m.start() != 0:
        raise ParseError(
            f"input must start with a numeric value, got {s[:20]!r}"
            + ("" if m is None else f" (number found at offset {m.start()})")
        )
    value = float(m.group())
    rest = s[m.end():]

    if rest.strip() == "":
        return value, _dim_tuple({})

    if rest[0] not in " \t":
        raise ParseError(
            f"unexpected character {rest[0]!r} right after the number "
            f"{m.group()!r} (separate value and units with a space)"
        )
    expr = rest.strip()
    if not expr:
        return value, _dim_tuple({})

    factor, dim = _parse_unit_expression(expr)
    return value * factor, dim


def format_dimension(dim_tuple):
    """Format a dimension tuple canonically, e.g. (1, 0, -1, ...) -> 'm/s'."""
    num, den = [], []
    for name, exp in zip(BASE_NAMES, dim_tuple):
        if exp > 0:
            num.append(name if exp == 1 else f"{name}^{exp}")
        elif exp < 0:
            den.append(name if exp == -1 else f"{name}^{-exp}")
    if num and den:
        return "*".join(num) + "/" + "*".join(den)
    if num:
        return "*".join(num)
    if den:
        return "1/" + "*".join(den)
    return ""


def format_quantity(quantity):
    """Format a (value, dimension) pair so that it parses back identically."""
    value, dim = quantity
    unit_str = format_dimension(dim)
    # repr() of a float round-trips exactly through float()
    return f"{value!r} {unit_str}".strip()
